<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useAccountTable } from '@/utils/useAccountTable'
import { accountTableRequest } from '@/utils/accountTableRequest'
import AccountTypeFilter from '@/components/AccountTypeFilter.vue'
const accountTable = useAccountTable(), accountModes = accountTable.modes
const recipientTable = useAccountTable(), recipientModes = recipientTable.modes
const ledgerTable = useAccountTable(), ledgerModes = ledgerTable.modes
const request = accountTableRequest(accountTable)
import { can } from '@/utils/access'
const list=ref<any[]>([]), page=ref(1), total=ref(0), loading=ref(false), saving=ref(false), editor=ref(false), form=ref<any>({}), language=ref('zh-CN'), translations=ref<Record<string,any>>({})
const sendOpen=ref(false), selected=ref<any>(), ids=ref(''), sending=ref(false), sendResult=ref<any>(null)
const reportOpen=ref(false), stats=ref<any>({}), recipients=ref<any[]>([]), recipientPage=ref(1), recipientTotal=ref(0), filter=ref('ALL'), userFilter=ref(''), reportBusy=ref(false), ledgerOpen=ref(false), ledger=ref<any[]>([]), account=ref<any>({})
const languages=['zh-CN','zh-TW','en','ja','ko','fr','de','ru','es','pt','it','ar','tr','id','my','hi','cs','pl','th','vi']
const labels:Record<string,string>={DRAFT:'草稿',ACTIVE:'启用',PAUSED:'暂停',CLOSED:'关闭'}
const defaultCopy=()=>({title:'一份心意，开启更多可能',body:'为回馈新老客户，最近 {days} 天登录的客户可领取 {amount} U 体验金。点击下方按钮领取，体验金将自动存入您的专属账户。',terms:'体验金仅可用于交易，不可提现。交易净收益归入正式交易账户，体验金本金留在体验金账户。',open:'打开礼遇',close:'关闭',claim:'领取 {amount} U 体验金',success:'体验金已到账'})
const english=()=>({title:'A little extra for your next opportunity',body:'Thank you for trading with us. Customers who logged in within the last {days} days can claim {amount} U in trial credit.',terms:'Trial principal is for trading only and cannot be withdrawn. Net profits go to your real trading account.',open:'Open gift',close:'Close',claim:'Claim {amount} U',success:'Your trial credit has arrived'})
const activeCopy=computed(()=>translations.value[language.value] || {})
const preview=(key:string)=>String(activeCopy.value[key]||'').split('{amount}').join(String(form.value.amount||0)).split('{days}').join(String(form.value.recentLoginDays||0))
const date=(value:string)=>value?new Date(value+'Z').toLocaleString():'—'
async function load(){list.value=[];total.value=0;loading.value=true;try{const r:any=await request.get('/admin/activities',{params:{page:page.value-1}});list.value=r.content;total.value=r.totalElements}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}
function edit(row?:any, clone=false){
 accountTable.selectRow(row || {})
 form.value=row?JSON.parse(JSON.stringify(row)):{name:'新老客户 · 300 U 体验金',amount:300,recentLoginDays:3,maxClaims:1000,budget:300000,status:'DRAFT',template:false,autoPopup:true,animation:'GIFT',defaultLocale:'zh-CN',startsAt:null,endsAt:null}
 if(clone){delete form.value.id;form.value.name+=' · 副本';form.value.status='DRAFT';form.value.template=false;form.value.claimCount=0;form.value.granted=0}
 try{translations.value=row?JSON.parse(row.translations):{'zh-CN':defaultCopy(),en:english()}}catch{translations.value={'zh-CN':defaultCopy(),en:english()}}
 language.value=form.value.defaultLocale;editor.value=true
}
function addLanguage(code:string){if(!translations.value[code])translations.value[code]=code==='zh-CN'?defaultCopy():english();language.value=code}
async function save(){
 if(!form.value.name?.trim()||!translations.value[form.value.defaultLocale]){ElMessage.warning('请填写名称和默认语言');return}
 saving.value=true
 try{const payload={...form.value,translations:JSON.stringify(translations.value)};const r:any=await (payload.id?request.put(`/admin/activities/${payload.id}`,payload):request.post('/admin/activities',payload));form.value=r;editor.value=false;ElMessage.success('已保存，尚未自动发送');await load()}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}
}
async function status(row:any,value:string){
 accountTable.selectRow(row)
 try{await ElMessageBox.confirm(`确定${labels[value]}“${row.name}”？暂停/关闭只停止领取，不追缴已领取本金。`,'活动状态');await request.put(`/admin/activities/${row.id}`,{...row,status:value});await load()}catch(e:any){if(e?.message)ElMessage.error(e.message)}
}
function prepareSend(row:any){accountTable.selectRow(row);selected.value=row;ids.value='';sendResult.value=null;sendOpen.value=true}
const targetIds=computed(()=>[...new Set(ids.value.split(/[\s,，;；]+/).filter(Boolean))])
async function send(){
 if(!targetIds.value.length||targetIds.value.length>1000||targetIds.value.some(x=>!/^\d+$/.test(x)||!Number.isSafeInteger(Number(x))||Number(x)<=0)){ElMessage.warning('请输入1至1000个有效用户ID');return}
 sending.value=true
 try{await ElMessageBox.confirm(`向 ${targetIds.value.length} 位指定用户发送活动公告？每人可领取 ${selected.value.amount} U，实际领取仍受资格、期限和预算限制。`,'确认批量发送');sendResult.value=await request.post(`/admin/activities/${selected.value.id}/send`,targetIds.value.map(Number));ElMessage.success('投递已完成')}catch(e:any){if(e?.message)ElMessage.error(e.message)}finally{sending.value=false}
}
async function report(row?:any){if(row){recipientModes.value=[row.accountMode||"REAL"];selected.value=row;recipientPage.value=1;filter.value='ALL';userFilter.value='';reportOpen.value=true}recipients.value=[];stats.value={};reportBusy.value=true;try{const [s,r]:any=await Promise.all([recipientTable.counters(`/admin/activities/${selected.value.id}/stats`),recipientTable.fixedQuery(`/admin/activities/${selected.value.id}/recipients`,{page:recipientPage.value-1,state:filter.value,userId:userFilter.value||undefined},50)]);stats.value=s;recipients.value=r.content;recipientTotal.value=r.totalElements}catch(e:any){ElMessage.error(e.message)}finally{reportBusy.value=false}}
async function showLedger(userId:number, mode?:any){if(mode)ledgerModes.value=[mode];ledger.value=[];try{const [a,r]:any=await Promise.all([ledgerTable.counters(`/admin/activities/users/${userId}/account`),ledgerTable.fixedQuery(`/admin/activities/users/${userId}/ledger`,{},50)]);account.value={...a,userId};ledger.value=r.content;ledgerOpen.value=true}catch(e:any){ElMessage.error(e.message)}}
onMounted(load)
</script>
<template>
 <section class="activity-admin">
  <header class="activity-admin-hero"><div><span>CAMPAIGNS & TRIAL CREDIT</span><h2>把一份礼遇，送到合适的人手中。</h2><p>定向投递 · 多语言公告 · 独立本金账户 · 领取与互动追踪</p></div><el-button v-permission="'announcement:create'" v-if="can('announcement:create')" type="primary" size="large" @click="edit()" :disabled="accountModes.includes('DEMO') || !accountModes.length">＋ 新建活动</el-button></header>
  <div class="activity-admin-note">体验金与可提现资产隔离。新活动默认草稿，保存不等于发送；每个用户每个活动仅领取一次。</div>
  <AccountTypeFilter v-model="accountModes" @change="page=1;load()" /><admin-table :row-key="(row: any) => `${row.accountMode || 'REAL'}:${row.id ?? row.userId}:${row.type || ''}`" table-key="ActivityManagement.1" :data="list" v-loading="loading" stripe><el-table-column prop="accountModeLabel" label="账户类型" width="110" />
   <el-table-column prop="id" label="ID" width="65"/><el-table-column prop="name" label="活动 / 模板" min-width="230"><template #default="{row}"><strong>{{row.name}}</strong><el-tag v-if="row.template" size="small" style="margin-left:8px">模板</el-tag><small class="row-meta">{{row.defaultLocale}} · {{row.autoPopup?'自动弹出':'仅站内信'}} · {{row.animation}}</small></template></el-table-column>
   <el-table-column label="体验金" width="120"><template #default="{row}">{{Number(row.amount).toLocaleString()}} U</template></el-table-column>
   <el-table-column label="已领取 / 名额" width="145"><template #default="{row}">{{row.claimCount}} / {{row.maxClaims}}</template></el-table-column>
   <el-table-column label="已发 / 预算 (U)" width="165"><template #default="{row}">{{Number(row.granted).toLocaleString()}} / {{Number(row.budget).toLocaleString()}}</template></el-table-column>
   <el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':row.status==='CLOSED'?'info':'warning'">{{labels[row.status]}}</el-tag></template></el-table-column>
   <el-table-column label="截止时间" width="180"><template #default="{row}">{{date(row.endsAt)}}</template></el-table-column>
   <el-table-column label="操作" width="300" fixed="right"><template #default="{row}"><el-button v-permission="'announcement:edit'" v-if="can('announcement:edit')" link type="primary" @click="edit(row)" :disabled="accountModes.includes('DEMO') || !accountModes.length">编辑</el-button><el-button v-permission="'announcement:create'" v-if="can('announcement:create')" link type="primary" @click="edit(row,true)" :disabled="accountModes.includes('DEMO') || !accountModes.length">复制</el-button><el-button v-permission="'announcement:edit'" v-if="can('announcement:edit')" link type="primary" :disabled="accountModes.includes('DEMO') || !accountModes.length || (row.template||row.status!=='ACTIVE')" @click="prepareSend(row)">发送</el-button><el-button v-permission="'announcement:detail'" v-if="can('announcement:detail')" link type="primary" @click="report(row)">回执</el-button><el-button v-permission="'announcement:edit'" v-if="can('announcement:edit')" link @click="status(row,row.status==='ACTIVE'?'PAUSED':'ACTIVE')" :disabled="accountModes.includes('DEMO') || !accountModes.length">{{row.status==='ACTIVE'?'暂停':'启用'}}</el-button><el-button v-permission="'announcement:edit'" v-if="can('announcement:edit')" link type="danger" :disabled="accountModes.includes('DEMO') || !accountModes.length || (row.status==='CLOSED')" @click="status(row,'CLOSED')">关闭</el-button></template></el-table-column>
  </admin-table><el-pagination v-model:current-page="page" :page-size="50" :total="total" layout="total, prev, pager, next" @current-change="load"/>
  <el-dialog v-model="editor" :title="form.id?'编辑活动公告':'新建活动公告'" width="min(1120px,96vw)" :close-on-click-modal="false">
   <div class="activity-editor-layout"><el-form label-position="top" class="activity-form">
    <el-form-item label="后台活动名称" required><el-input v-model="form.name" maxlength="120"/></el-form-item>
    <div class="form-grid"><el-form-item label="活动状态"><el-select v-model="form.status"><el-option v-for="(label,key) in labels" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="保存类型"><el-switch v-permission="form.id ? 'announcement:edit' : 'announcement:create'" v-model="form.template" active-text="可复用模板" inactive-text="投放活动"/></el-form-item></div>
    <div class="form-grid"><el-form-item label="每人体验金 (U)" required><el-input-number v-model="form.amount" :min="0.01" :max="1000000" :precision="2"/></el-form-item><el-form-item label="最近登录天数（0 表示不限）"><el-input-number v-model="form.recentLoginDays" :min="0" :max="365" :precision="0"/></el-form-item><el-form-item label="最多领取人数"><el-input-number v-model="form.maxClaims" :min="1" :max="1000000" :precision="0"/></el-form-item><el-form-item label="发放总预算 (U)"><el-input-number v-model="form.budget" :min="form.amount" :max="1000000000" :precision="2"/></el-form-item></div>
    <div class="form-grid"><el-form-item label="开始时间（UTC，可留空）"><el-date-picker v-model="form.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="立即生效"/></el-form-item><el-form-item label="结束时间（UTC，可留空）"><el-date-picker v-model="form.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="不限期限"/></el-form-item></div>
    <div class="form-grid"><el-form-item label="进入页面自动弹出"><el-switch v-permission="form.id ? 'announcement:edit' : 'announcement:create'" v-model="form.autoPopup"/></el-form-item><el-form-item label="动画风格"><el-select v-model="form.animation"><el-option label="礼盒开启 + 彩带" value="GIFT"/><el-option label="金色礼遇 + 彩带" value="CONFETTI"/><el-option label="静态展示" value="NONE"/></el-select></el-form-item></div>
    <el-divider content-position="left">多语言文案 · 支持 {amount} / {days} 参数</el-divider>
    <div class="form-grid"><el-form-item label="编辑语言"><el-select :model-value="language" @change="addLanguage"><el-option v-for="code in languages" :key="code" :label="code+(translations[code]?' · 已配置':' · 新增')" :value="code"/></el-select></el-form-item><el-form-item label="未配置语言的回退语言"><el-select v-model="form.defaultLocale"><el-option v-for="(_,code) in translations" :key="code" :label="String(code)" :value="code"/></el-select></el-form-item></div>
    <template v-if="translations[language]"><el-form-item label="客户看到的标题" required><el-input v-model="translations[language].title" maxlength="160"/></el-form-item><el-form-item label="活动正文" required><el-input v-model="translations[language].body" type="textarea" :rows="4" maxlength="10000"/></el-form-item><el-form-item label="细则小字" required><el-input v-model="translations[language].terms" type="textarea" :rows="3" maxlength="10000"/></el-form-item><div class="form-grid"><el-form-item v-for="(label,key) in {open:'打开按钮',close:'关闭按钮',claim:'领取按钮',success:'领取成功提示'}" :key="key" :label="label"><el-input v-model="translations[language][key]" maxlength="200"/></el-form-item></div><el-button v-permission="form.id ? 'announcement:edit' : 'announcement:create'" v-if="language!==form.defaultLocale" link type="danger" @click="delete translations[language];language=form.defaultLocale">移除此语言（客户将使用回退语言）</el-button></template>
   </el-form><aside class="activity-preview-wrap"><small>客户视角预览 · {{language}}</small><div class="activity-preview"><div class="preview-reward"><span>EXCLUSIVE REWARD</span><div class="preview-gift">✦</div><strong>{{Number(form.amount||0).toLocaleString()}}<small> U</small></strong><p>领取后自动入账，无需充值</p></div><div class="preview-body"><h3>{{preview('title')}}</h3><p>{{preview('body')}}</p><div>{{preview('terms')}}</div><button v-permission="'session:self'" type="button">{{preview('claim')||'立即领取'}}</button></div></div><p class="preview-note">文本安全渲染，不支持 HTML / JavaScript。体验金本金不可提现或划转；实名规则不可被文案配置覆盖。</p></aside></div>
   <template #footer><el-button v-permission="'session:close'" @click="editor=false">取消</el-button><el-button v-permission="form.id ? 'announcement:edit' : 'announcement:create'" type="primary" :loading="saving" @click="save">保存{{form.template?'模板':'活动'}}</el-button></template>
  </el-dialog>
  <el-dialog v-model="sendOpen" title="定向批量发送" width="640px"><p>{{selected?.name}} · 每人 {{selected?.amount}} U</p><el-alert type="info" :closable="false" title="仅向指定且符合资格的用户投递。重复发送不会重复创建消息或发放本金。"/><el-input v-model="ids" type="textarea" :rows="8" placeholder="粘贴用户ID，支持逗号、空格或换行分隔；每批最多1000人" style="margin-top:18px"/><p>已识别 {{targetIds.length}} 个独立用户ID</p><el-alert v-if="sendResult" type="success" :closable="false" :title="`新增发送 ${sendResult.sent}，已发送跳过 ${sendResult.duplicates}，资格不符 ${sendResult.ineligible}`"/><template #footer><el-button v-permission="'session:close'" @click="sendOpen=false">关闭</el-button><el-button v-permission="'announcement:edit'" type="primary" :loading="sending" @click="send" :disabled="accountModes.includes('DEMO') || !accountModes.length">确认发送</el-button></template></el-dialog>
  <el-dialog v-model="reportOpen" :title="'投递与领取追踪 · '+(selected?.name||'')" width="min(1200px,96vw)"><div class="activity-stat-grid"><div v-for="(label,key) in {sent:'已发送',received:'已收到',opened:'已打开',closed:'已关闭',closedWithoutOpening:'未打开即关闭',claimed:'已领取'}" :key="key"><strong>{{stats[key]||0}}</strong><span>{{label}}</span></div></div><div class="recipient-filters"><el-select v-model="filter" @change="recipientPage=1;report()"><el-option v-for="(label,key) in {ALL:'全部',SENT:'发送但未收到',RECEIVED:'已收到',OPENED:'已打开',CLOSED:'已关闭',CLOSED_UNOPENED:'收到后未打开即关闭',CLAIMED:'已领取'}" :key="key" :value="key" :label="label"/></el-select><el-input v-model="userFilter" placeholder="用户ID" clearable style="width:180px" @change="recipientPage=1;report()"/><el-button v-permission="'announcement:detail'" :loading="reportBusy" @click="report()">刷新</el-button></div><AccountTypeFilter v-model="recipientModes" @change="recipientPage=1;report()" /><admin-table :row-key="(row: any) => `${row.accountMode || 'REAL'}:${row.id ?? row.userId}:${row.type || ''}`" table-key="ActivityManagement.2" :data="recipients" v-loading="reportBusy"><el-table-column prop="accountModeLabel" label="账户类型" width="110" /><el-table-column prop="userId" label="用户ID" width="105"/><el-table-column v-for="(label,key) in {sentAt:'发送时间',receivedAt:'收到时间',openedAt:'首次打开',closedAt:'最后关闭',claimedAt:'领取时间'}" :key="key" :label="label" min-width="155"><template #default="{row}">{{date(row[key])}}</template></el-table-column><el-table-column label="打开/关闭" width="100"><template #default="{row}">{{row.openCount}} / {{row.closeCount}}</template></el-table-column><el-table-column label="账户" width="80"><template #default="{row}"><el-button v-permission="'announcement:detail'" link type="primary" @click="showLedger(row.userId,row.accountMode)">流水</el-button></template></el-table-column></admin-table><el-pagination v-model:current-page="recipientPage" :page-size="50" :total="recipientTotal" layout="total,prev,pager,next" @current-change="report()"/></el-dialog>
  <el-dialog v-model="ledgerOpen" title="体验金账户与最近50笔流水" width="min(900px,95vw)"><p>用户 {{account.userId}} · 可用 {{Number(account.available)}} U · 占用 {{Number(account.frozen)}} U · 累计消耗 {{Number(account.consumed)}} U · 净收益 {{Number(account.profits)}} U</p><AccountTypeFilter v-model="ledgerModes" @change="showLedger(account.userId)" /><admin-table :row-key="(row: any) => `${row.accountMode || 'REAL'}:${row.id ?? row.userId}:${row.type || ''}`" table-key="ActivityManagement.3" :data="ledger"><el-table-column prop="accountModeLabel" label="账户类型" width="110" /><el-table-column prop="reason" label="业务原因" min-width="200"/><el-table-column prop="delta" label="本金变化"/><el-table-column prop="available" label="可用"/><el-table-column prop="frozen" label="冻结"/><el-table-column label="时间" width="180"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column></admin-table></el-dialog>
 </section>
</template>
<style scoped>
