ody button{margin-top:20px;width:100%;border:0;border-radius:9px;padding:13px;background:#73b100;color:#fff}.preview-note{font-size:11px;line-height:1.8;color:#98a18b;margin:18px 8px}.activity-stat-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-bottom:20px}.activity-stat-grid>div{background:#f5f8ef;border:1px solid #e7ecdF;padding:16px;border-radius:10px}.activity-stat-grid strong{display:block;font-size:26px;color:#557532}.activity-stat-grid span{font-size:11px;color:#89977a}.recipient-filters{display:flex;gap:12px;margin-bottom:18px}.recipient-filters>.el-select{width:220px}@media(max-width:850px){.activity-editor-layout{grid-template-columns:1fr}.activity-preview-wrap{display:none}.activity-stat-grid{grid-template-columns:repeat(3,1fr)}.activity-admin-hero{padding:20px}.activity-admin-hero h2{font-size:18px}}
